window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-56709e113b2321c5"]={"versions": [{"id": "FIG-56709e113b2321c5", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Service-Bedarfe in der AUTOSAR Classic Platform (AUTOSAR_SoftwareComponentTemplate). Es beschreibt die statische Verankerung der Kommunikationsmanager-Nutzeranforderungen (<code>SwcComMgrUserNeeds</code>) innerhalb des internen Verhaltens einer Software-Komponente (<code>InternalBehavior</code>) und deren Zuordnung zu Service-Ports (<code>PortPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>SwcInternalBehavior::InternalBehavior</strong> (Spezialisierung von <code>ARElement</code>): Besitzt das Attribut <code>supportsMultipleInstantiation: Boolean</code> und aggregiert über die Kompositionsrolle <code>+serviceNeeds</code> mit Kardinalität <code>0..*</code> Instanzen von <code>ServiceNeeds</code>.\n</li><li><strong>ServiceNeeds::ServiceNeeds</strong> (Spezialisierung von <code>Identifiable</code>): Abstrakte Basisklasse für Service-Bedarfe.\n</li><li><strong>ServiceNeeds::ComMgrUserNeeds</strong>: Spezialisiert <code>ServiceNeeds</code>; deklariert das Attribut <code>+maxCommMode: MaxCommModeEnum</code>.\n</li><li><strong>SwcComMgrUserNeeds</strong>: Spezialisiert <code>ComMgrUserNeeds</code>; repräsentiert die SWC-spezifischen ComM-Bedarfe. Aggregiert:\n<ul class=\"fig-list\"><li><code>+serviceCallPort</code> (<code>0..*</code>): Komposition von <code>RoleBasedRPortAssignment</code>.\n</li><li><code>+callbackPort</code> (<code>0..*</code>): Komposition von <code>RoleBasedPPortAssignment</code>.\n</li></ul>\n</li><li><strong>RoleBasedRPortAssignment</strong>: Enthält das Attribut <code>+role: Identifier</code> und referenziert assoziativ über <code>+rPortPrototype</code> mit Kardinalität <code>1</code> ein <code>Components::RPortPrototype</code> («atpPrototype», spezialisiert <code>PortPrototype</code>).\n</li><li><strong>RoleBasedPPortAssignment</strong>: Enthält das Attribut <code>+role: Identifier</code> und referenziert assoziativ über <code>+pPortPrototype</code> mit Kardinalität <code>1</code> ein <code>Components::PPortPrototype</code> («atpPrototype», spezialisiert <code>PortPrototype</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Metamodellstruktur ohne Verhaltens- oder Sequenzpfade. Zur Laufzeit bzw. Generierungszeit dient die Konfiguration dazu, dass eine Software-Komponente über ihren <code>RPortPrototype</code> Dienstaufrufe an den Communication Manager (ComM) absetzt (z. B. Anforderung eines Kommunikationsmodus bis zu <code>maxCommMode</code>) und über den zugeordneten <code>PPortPrototype</code> Rückmeldungen oder Benachrichtigungen (Callbacks) des ComM entgegennimmt. Die Bindung erfolgt rollenbasiert über den Bezeichner <code>role</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell ist normativ für die formale Beschreibung der Interaktion zwischen einer atomaren Software-Komponente und dem BSW-Modul ComM. Entwickler und Generierungswerkzeuge müssen sicherstellen, dass bei Definition von <code>SwcComMgrUserNeeds</code> jeder zugewiesene <code>RoleBasedRPortAssignment</code> und <code>RoleBasedPPortAssignment</code> genau einen korrespondierenden Port-Prototyp (<code>rPortPrototype</code> bzw. <code>pPortPrototype</code>) referenziert. Der Modusbedarf wird über die Enumeration <code>MaxCommModeEnum</code> typisiert.</p>"}, {"id": "FIG-406dd0b11761588a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Service-Bedarfe in der AUTOSAR Classic Platform (AUTOSAR_SoftwareComponentTemplate). Es beschreibt die statische Verankerung der Kommunikationsmanager-Nutzeranforderungen (<code>SwcComMgrUserNeeds</code>) innerhalb des internen Verhaltens einer Software-Komponente (<code>InternalBehavior</code>) und deren Zuordnung zu Service-Ports (<code>PortPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>SwcInternalBehavior::InternalBehavior</strong> (Spezialisierung von <code>ARElement</code>): Besitzt das Attribut <code>supportsMultipleInstantiation: Boolean</code> und aggregiert über die Kompositionsrolle <code>+serviceNeeds</code> mit Kardinalität <code>0..*</code> Instanzen von <code>ServiceNeeds</code>.\n</li><li><strong>ServiceNeeds::ServiceNeeds</strong> (Spezialisierung von <code>Identifiable</code>): Abstrakte Basisklasse für Service-Bedarfe.\n</li><li><strong>ServiceNeeds::ComMgrUserNeeds</strong>: Spezialisiert <code>ServiceNeeds</code>; deklariert das Attribut <code>+maxCommMode: MaxCommModeEnum</code>.\n</li><li><strong>SwcComMgrUserNeeds</strong>: Spezialisiert <code>ComMgrUserNeeds</code>; repräsentiert die SWC-spezifischen ComM-Bedarfe. Aggregiert:\n<ul class=\"fig-list\"><li><code>+serviceCallPort</code> (<code>0..*</code>): Komposition von <code>RoleBasedRPortAssignment</code>.\n</li><li><code>+callbackPort</code> (<code>0..*</code>): Komposition von <code>RoleBasedPPortAssignment</code>.\n</li></ul>\n</li><li><strong>RoleBasedRPortAssignment</strong>: Enthält das Attribut <code>+role: Identifier</code> und referenziert assoziativ über <code>+rPortPrototype</code> mit Kardinalität <code>1</code> ein <code>Components::RPortPrototype</code> («atpPrototype», spezialisiert <code>PortPrototype</code>).\n</li><li><strong>RoleBasedPPortAssignment</strong>: Enthält das Attribut <code>+role: Identifier</code> und referenziert assoziativ über <code>+pPortPrototype</code> mit Kardinalität <code>1</code> ein <code>Components::PPortPrototype</code> («atpPrototype», spezialisiert <code>PortPrototype</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Metamodellstruktur ohne Verhaltens- oder Sequenzpfade. Zur Laufzeit bzw. Generierungszeit dient die Konfiguration dazu, dass eine Software-Komponente über ihren <code>RPortPrototype</code> Dienstaufrufe an den Communication Manager (ComM) absetzt (z. B. Anforderung eines Kommunikationsmodus bis zu <code>maxCommMode</code>) und über den zugeordneten <code>PPortPrototype</code> Rückmeldungen oder Benachrichtigungen (Callbacks) des ComM entgegennimmt. Die Bindung erfolgt rollenbasiert über den Bezeichner <code>role</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell ist normativ für die formale Beschreibung der Interaktion zwischen einer atomaren Software-Komponente und dem BSW-Modul ComM. Entwickler und Generierungswerkzeuge müssen sicherstellen, dass bei Definition von <code>SwcComMgrUserNeeds</code> jeder zugewiesene <code>RoleBasedRPortAssignment</code> und <code>RoleBasedPPortAssignment</code> genau einen korrespondierenden Port-Prototyp (<code>rPortPrototype</code> bzw. <code>pPortPrototype</code>) referenziert. Der Modusbedarf wird über die Enumeration <code>MaxCommModeEnum</code> typisiert.</p>"}], "trans": [{"from": "FIG-56709e113b2321c5", "to": "FIG-406dd0b11761588a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
